import "./AlertBanner.css";

export interface AlertBannerProps {
  message: string;
  onRetry: () => void;
}

export function AlertBanner({ message, onRetry }: AlertBannerProps) {
  return (
    <div className="alert-banner" role="alert">
      <p className="alert-banner__message">{message}</p>
      <button
        type="button"
        className="alert-banner__retry"
        onClick={onRetry}
      >
        Retry
      </button>
    </div>
  );
}
```

```css
/*
 * AlertBanner styles.
 * Day is the default. Night applies when an ancestor (typically <html>)
 * carries data-theme="night". Colors are exposed as custom properties so
 * the banner follows the active theme without extra logic in the component.
 */

:root {
  --alert-banner-bg: #fdf1ee;
  --alert-banner-border: #d9735f;
  --alert-banner-text: #6b2415;
  --alert-banner-button-bg: #b4432c;
  --alert-banner-button-text: #ffffff;
  --alert-banner-button-hover: #9a3822;
  --alert-banner-focus: #1f5fbf;
}

[data-theme="night"] {
  --alert-banner-bg: #2a1714;
  --alert-banner-border: #c9604b;
  --alert-banner-text: #f6d6cc;
  --alert-banner-button-bg: #e08a74;
  --alert-banner-button-text: #2a1714;
  --alert-banner-button-hover: #eca08b;
  --alert-banner-focus: #9cc4ff;
}

.alert-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--alert-banner-border);
  border-left-width: 4px;
  border-radius: 8px;
  background-color: var(--alert-banner-bg);
  color: var(--alert-banner-text);
  font-family: inherit;
  font-size: 0.95rem;
  line-height: 1.4;
}

.alert-banner__message {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}

.alert-banner__retry {
  flex: 0 0 auto;
  min-height: 44px;
  min-width: 44px;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 6px;
  background-color: var(--alert-banner-button-bg);
  color: var(--alert-banner-button-text);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 120ms ease;
}

.alert-banner__retry:hover {
  background-color: var(--alert-banner-button-hover);
}

.alert-banner__retry:focus-visible {
  outline: 3px solid var(--alert-banner-focus);
  outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
  .alert-banner__retry {
    transition: none;
  }
}
```

